t.script:
document.getElementById('start_date').addEventListener('change', checkAvailability);
document.getElementById('end_date').addEventListener('change', checkAvailability);

function showMessage(elementId, message, isError = false) {
    const element = document.getElementById(elementId);
    if (!element) return;

    if (isError) {
        element.innerHTML = '❌ ' + (message || 'Une erreur est survenue');
        element.className = 'alert alert-danger';
    } else {
        element.innerHTML = '✅ ' + (message || 'Disponible');
        element.className = 'alert alert-success';
    }
    element.style.display = 'block';
}

function checkAvailability() {
    const startDate = document.getElementById('start_date').value;
    const endDate = document.getElementById('end_date').value;

    if (!startDate || !endDate) {
        document.getElementById('price_info').style.display = 'none';
        return;
    }

    fetch('/onedesk/unit/' + unitId + '/availability', {
        method: 'POST',
        headers: {
            'Content-Type': 'application/json',
            'X-CSRF-Token': csrfToken,
        },
        body: JSON.stringify({
            start_date: startDate,
            end_date: endDate,
        })
    })
    .then(r => {
        if (!r.ok) throw new Error('Erreur serveur: ' + r.status);
        return r.json();
    })
    .then(data => {
        console.log('Availability response:', data);
        if (data && data.available) {
            document.getElementById('price_info').innerHTML =
                '<p class="mb-1"><strong>✅ Disponible!</strong></p>' +
                '<p class="mb-1"><strong>Nuits:</strong> ' + (data.nights || 0) + '</p>' +
                '<p class="mb-1"><strong>Prix par nuit:</strong> ' + (data.price_per_night ? data.price_per_night.toFixed(2) : '0') + '€</p>' +
                '<hr/>' +
                '<p class="mb-1"><strong>Prix total:</strong> <span class="h5">' + (data.total_with_cleaning ? data.total_with_cleaning.toFixed(2) : '0') + '</span>€</p>';
            document.getElementById('price_info').className = 'alert alert-success';
            document.getElementById('price_info').style.display = 'block';
        } else {
            document.getElementById('price_info').style.display = 'none';
        }
    })
    .catch(error => {
        console.error('Availability error:', error);
        document.getElementById('price_info').style.display = 'none';
    });
}

document.getElementById('booking_form').addEventListener('submit', function(e) {
    e.preventDefault();

    const startDate = document.getElementById('start_date').value;
    const endDate = document.getElementById('end_date').value;
    const name = document.getElementById('name').value;
    const email = document.getElementById('email').value;

    console.log('Form submission:', { startDate, endDate, name, email });

    fetch('/onedesk/booking', {
        method: 'POST',
        headers: {
            'Content-Type': 'application/json',
            'X-CSRF-Token': csrfToken,
        },
        body: JSON.stringify({
            unit_id: unitId,
            name: name,
            email: email,
            phone: document.getElementById('phone').value,
            start_date: startDate,
            end_date: endDate,
            message: document.getElementById('message').value,
        })
    })
    .then(r => {
        console.log('Response status:', r.status, r.ok);
        console.log('Response content-type:', r.headers.get('content-type'));

        // Toujours lire le texte brut d'abord pour debugger
        return r.text().then(text => {
            console.log('Raw response text:', text);

            // Parser le JSON
            let data = {};
            try {
                data = JSON.parse(text);
                console.log('Parsed JSON:', data);
            } catch (e) {
                console.error('JSON parse error:', e);
                data = { message: text || 'Réponse invalide du serveur' };
            }

            // Si statut HTTP n'est pas ok, créer une erreur
            if (!r.ok) {
                throw new Error('HTTP ' + r.status + ': ' + (data.message || 'Erreur serveur'));
            }

            return data;
        });
    })
    .then(data => {
        console.log('Final booking response:', data);

        if (data && data.status === 'success') {
            alert(data.message || '✅ Réservation confirmée!');
            document.getElementById('booking_form').reset();
            document.getElementById('price_info').style.display = 'none';
        } else if (data && data.message) {
            alert(data.message);
        } else {
            console.error('Unexpected response:', data);
            alert('Une erreur est survenue lors de la réservation');
        }
    })
    .catch(error => {
        console.error('Booking error:', error);
        alert(error.message || 'Erreur lors de la réservation');
    });
});
